<?php
defined( 'ABSPATH' ) || exit;
final class HE_SEO {
	public function hooks() { add_action( 'wp_head', array( $this, 'schema' ), 20 ); }
	public function schema() { if ( ! is_singular( HE_Content::TYPE ) ) { return; } $id = get_queried_object_id(); $type = HE_Content::type( $id, 'slug' ); $author = absint( get_post_field( 'post_author', $id ) ); $reviewer = absint( HE_Content::meta( $id, 'reviewer_id' ) ); $medical = in_array( $type, array( 'health-condition', 'pathology', 'anatomy', 'body-system', 'symptom' ), true ); $data = array( '@context' => 'https://schema.org', '@type' => $medical ? 'MedicalWebPage' : 'Article', 'name' => get_the_title( $id ), 'headline' => get_the_title( $id ), 'description' => wp_strip_all_tags( get_the_excerpt( $id ) ), 'inLanguage' => 'en-US', 'datePublished' => get_the_date( DATE_W3C, $id ), 'dateModified' => get_the_modified_date( DATE_W3C, $id ), 'url' => get_permalink( $id ), 'about' => array( '@type' => 'DefinedTerm', 'name' => get_the_title( $id ), 'description' => wp_strip_all_tags( get_the_excerpt( $id ) ), 'inDefinedTermSet' => home_url( '/homeopathy-encyclopedia/' ) ), 'author' => array( '@type' => 'Person', 'name' => get_the_author_meta( 'display_name', $author ), 'url' => HE_Permissions::profile( $author ) ), 'publisher' => array( '@type' => 'Organization', 'name' => 'Sabri Social Homeopathy Platform', 'url' => home_url( '/' ) ) ); if ( $reviewer ) { $data['reviewedBy'] = array( '@type' => 'Person', 'name' => get_the_author_meta( 'display_name', $reviewer ) ); $data['lastReviewed'] = get_the_modified_date( 'Y-m-d', $id ); } echo '<script type="application/ld+json">' . wp_json_encode( $data, JSON_UNESCAPED_UNICODE | JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT ) . '</script>'; }
}

